// Next.js Frontend - example in axios call
import axios from 'axios';

async function callBackendApi(endpoint: string, data: any, timeout: number = 9000): Promise<any> {
  try {
    const response = await axios.post(
      endpoint,
      data,
      {
        headers: {
          Authorization: `Bearer ${yourJwtToken}`,
        },
        timeout: timeout, // Timeout in milliseconds
      }
    );
    return response.data;
  } catch (error) {
    if (axios.isAxiosError(error) && error.code === 'ECONNABORTED') {
      console.error('Backend API call timed out:', error.message);
      // Specific error handling for timeout (AC4)
      throw new Error('Operation timed out. Please try again.');
    }
    console.error('Error calling backend API:', error);
    throw error;
  }
}
